"use strict";

// Feeds the shared viewer (app.js, the same page `agent-graph view` serves)
// from this site instead of a local server. The log's text is fetched from
// the API in chunks, and graphs and timelines are computed right here by
// Agent Graph's reducer, compiled to WebAssembly: the same code as the CLI.
//
// Hand-written; everything else in this folder is generated by
// scripts/sync-viewer.mjs.

(async () => {
  const config = JSON.parse(document.getElementById("agent-graph-config").textContent);
  const enc = new TextEncoder();
  const dec = new TextDecoder();
  const exact = new TextDecoder("utf-8", { ignoreBOM: true });

  const wasm = await loadWasm("/viewer/agent_graph.wasm");

  // Strings cross into WebAssembly as UTF-8 bytes in its memory.
  function put(text) {
    return putBytes(enc.encode(text));
  }

  function putBytes(bytes) {
    const ptr = wasm.alloc(bytes.length);
    new Uint8Array(wasm.memory.buffer, ptr, bytes.length).set(bytes);
    return [ptr, bytes.length];
  }

  function call(request) {
    const [ptr, len] = put(JSON.stringify(request));
    const out = wasm.query(ptr, len);
    wasm.dealloc(ptr, len);
    const n = wasm.result_len();
    const text = dec.decode(new Uint8Array(wasm.memory.buffer, out, n));
    wasm.dealloc(out, n);
    return JSON.parse(text);
  }

  function reply(request) {
    const result = call(request);
    if (result && result.error) throw new Error(`${result.status} ${result.error}`);
    return result;
  }

  // Fetches the chunks we don't have yet. Returns whether any events arrived.
  let after = "";
  // Where the next text read should start. A log's chunks are stored one
  // after another, so a read that starts anywhere else, with a keyframe,
  // means its start was trimmed as we read it (a live share keeps only its
  // last two keyframes' worth), perhaps only partway so far: what we hold is
  // broken, so we start again from that keyframe (a trim cuts only at one).
  // A gap that isn't a trim's (a log written with one) is read past.
  let next = null;
  async function pull() {
    let added = 0;
    for (;;) {
      const res = await fetch(`/api/logs/${config.id}/content?after=${after}`, { cache: "no-store" });
      if (res.status === 401) {
        location.reload(); // the password cookie expired; the page asks again
        return false;
      }
      if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
      // Its bytes, as stored: a byte-order mark at its start is kept (text()
      // would drop it, and so miscount where the next read starts).
      const bytes = new Uint8Array(await res.arrayBuffer());
      const first = res.headers.get("x-first-chunk");
      if (bytes.length && first !== null) {
        const line = bytes.indexOf(10);
        const head = exact.decode(line < 0 ? bytes : bytes.subarray(0, line));
        if (next !== null && Number(first) !== next && startsWithKeyframe(head)) {
          wasm.reset();
          added++;
        }
        next = Number(first) + bytes.length;
      }
      if (bytes.length) {
        const [ptr, len] = putBytes(bytes);
        added += wasm.append(ptr, len);
        wasm.dealloc(ptr, len);
      }
      after = res.headers.get("x-last-chunk") || after;
      if (res.headers.get("x-more") !== "1") return added > 0;
    }
  }

  await pull();

  // A log being streamed is judged against the clock ("stale?", "5m ago").
  // A pasted one is shown as it stood at its last event.
  const now = () => (config.live ? Date.now() : null);

  window.agentGraphSource = {
    // "site": the graph is shown away from the computer the sessions ran on,
    // so it offers nothing to open.
    graph: async (until, root) =>
      reply({ op: "graph", env: "site", until: until || null, root: root || null, now_ms: now() }),
    timeline: async (root) => reply({ op: "timeline", root, now_ms: now() }),
    info: async () => {
      const info = call({ op: "info" });
      return { now_ms: config.live ? Date.now() : info.last_event_ms, where: null };
    },
    subscribe(onChange, onStatus) {
      onStatus(true);
      if (!config.live) return;
      // Poll gently: every 3 s while events are arriving, backing off to 15 s
      // when quiet or when the tab is hidden.
      let delay = 3000;
      const tick = async () => {
        try {
          if (await pull()) {
            delay = 3000;
            onChange();
          } else {
            delay = Math.min(delay * 1.5, 15000);
          }
          onStatus(true);
        } catch {
          onStatus(false);
          delay = 10000;
        }
        setTimeout(tick, document.hidden ? Math.max(delay, 15000) : delay);
      };
      setTimeout(tick, delay);
      document.addEventListener("visibilitychange", () => {
        if (!document.hidden) delay = 3000;
      });
    },
    imageUrl: null,
    liveLabel: config.live ? "Live" : "Latest",
  };

  const script = document.createElement("script");
  script.src = "/viewer/app.js";
  document.body.appendChild(script);
})().catch((err) => {
  const note = document.createElement("p");
  note.className = "banner";
  note.textContent = `Couldn't load this log: ${err.message}`;
  (document.getElementById("view") || document.body).prepend(note);
});

function startsWithKeyframe(text) {
  const end = text.indexOf("\n");
  try {
    return JSON.parse(end < 0 ? text : text.slice(0, end)).type === "keyframe";
  } catch {
    return false;
  }
}

async function loadWasm(url) {
  if (WebAssembly.instantiateStreaming) {
    try {
      return (await WebAssembly.instantiateStreaming(fetch(url), {})).instance.exports;
    } catch {
      // Falls through: some servers send the wrong content type.
    }
  }
  const bytes = await (await fetch(url)).arrayBuffer();
  return (await WebAssembly.instantiate(bytes, {})).instance.exports;
}
